	public boolean isApplicableToInventory(int itemId)
	{
		return itemId == ItemID.SKILLCAPE_MAX ||
				itemId == ItemID.SKILLCAPE_CONSTRUCTION ||
				itemId == ItemID.SKILLCAPE_CONSTRUCTION_TRIMMED ||
				itemId == ItemID.SKILLCAPE_FARMING ||
